def pluck(arr):
    if not arr:
        return []
    min_even = None
    index = -1
    for i, num in enumerate(arr):
        if num % 2 == 0:
            if min_even is None:
                min_even = num
                index = i
            else:
                if num < min_even:
                    min_even = num
                    index = i
                elif num == min_even:
                    if i < index:
                        index = i
    return [min_even, index] if min_even is not None else []
