def file_name_check(file_name):
    digits = file_name.count('0123456789')
    if digits > 3:
        return 'No'
    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'
    prefix = parts[0]
    if not prefix:
        return 'No'
    if not prefix[0].isalpha():
        return 'No'
    suffix = parts[1]
    if suffix not in ['txt', 'exe', 'dll']:
        return 'No'
    return 'Yes'
