import math

def bell_number(n):
    if n == 0:
        return 1
    bell = [0] * (n + 1)
    bell[0] = 1
    for i in range(1, n + 1):
        for k in range(i):
            bell[i] += math.comb(i - 1, k) * bell[k]
    return bell[n]

