def comb_sort(arr):
    gap = len(arr) // 2
    while gap > 1:
        for i in range(0, len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
        gap = int(gap / 1.3)
    return arr

