def eulerian_num(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m > n - 1:
        return 0

    # Initialize a 2D DP table with size (n+1) x (m+1)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # Base case

    for i in range(1, n + 1):
        for j in range(0, m + 1):
            if j == 0:
                dp[i][j] = i * dp[i - 1][j]
            else:
                dp[i][j] = (i - j) * dp[i - 1][j] + (j + 1) * dp[i - 1][j - 1]

    return dp[n][m]

