    def sum_proper_divisors(n):
        if n == 1:
            return 0
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                if i != n // i:
                    total += i + n // i
                else:
                    total += i
        return total

    total = 0
    for n in range(1, N + 1):
        s = sum_proper_divisors(n)
        if s == n:
            continue
        if s <= N and s != n:
            if sum_proper_divisors(s) == n:
                total += n
    return total

