import math

def sum_amicable_numbers(n):
    def sum_proper_divisors(x):
        if x == 1:
            return 0
        total = 1  # 1 is a proper divisor of all x > 1
        sqrt_x = int(math.sqrt(x))
        for i in range(2, sqrt_x + 1):
            if x % i == 0:
                total += i
                if i != x // i:
