def find_length(s):
    prefix = [0]
    for c in s:
        if c == '0':
            prefix.append(prefix[-1] + 1)
        else:
            prefix.append(prefix[-1] - 1)
    max_diff = -float('inf')
    min_prefix = prefix[0]
    for j in range(1, len(prefix)):
        current_diff = prefix[j] - min_prefix
        if current_diff > max_diff:
            max_diff = current_diff
        if prefix[j] < min_prefix:
            min_prefix = prefix[j]
    return max_diff

assert find_length("11000010001") == 6
