def reverse_vowels(s):
    vowels = 'aeiou'
    vowels_in_order = [c for c in s if c in vowels]
    reversed_vowels = vowels_in_order[::-1]
    result = []
    index = 0
    for c in s:
        if c in vowels:
            result.append(reversed_vowels[index])
            index += 1
        else:
            result.append(c)
    return ''.join(result)

assert reverse_vowels("Python") == "Python"
