import math

def zero_ratio(arr):
    zeros = 0
    non_zeros = 0
    for num in arr:
        if num == 0:
            zeros += 1
        else:
            non_zeros += 1
    if non_zeros == 0:
        return 0.0
    return zeros / non_zeros

assert math.isclose(zero_ratio([0, 1, 2, -1, -5, 6, 0, -3, -2, 3, 4, 6, 8]), 0.181818, rel_tol=0.001)
