def pancake_sort(lst):
    n = len(lst)
    for i in range(n, 0, -1):
        max_idx = i - 1
        for j in range(i):
            if lst[j] > lst[max_idx]:
                max_idx = j
        if max_idx != i - 1:
            # Flip to bring max to the top
            lst = lst[:max_idx][::-1] + lst[max_idx:]
            # Flip to bring max to the end of the unsorted part
            lst = lst[:i][::-1] + lst[i:]
    return lst

