    arr[start:end+1] = arr[start:end+1][::-1]
    return arr

def pancake_sort(arr):
    n = len(arr)
    for i in range(n-1, 0, -1):
        # Find the index of the maximum element in the first i elements
        max_index = i
        for j in range(i):
            if arr[j] > arr[max_index]:
                max_index = j
        # Flip to the top
