import math

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return (g, x, y)

def find_solution(a, b, n):
    g, x, y = extended_gcd(a, b)
    if n % g != 0:
        return None
    else:
        x *= (n // g)
        y *= (n // g)
        return (x, y)

# Example usage
print(find_solution(2, 3, 7))  # Output: (-7, 7)

