    for num in arr:
        if count == 0:
            candidate = num
        if num == candidate:
            count += 1
        else:
            count -= 1

    if candidate != x:
        return False

    first = bisect.bisect_left(arr, x)
    last = bisect.bisect_right(arr, x) - 1
    return (last - first + 1) > n / 2

