def max_sum_increasing_subseq(arr, i, k, n):
    dp = [0] * n
    max_sum = float('-inf')

    for j in range(n):
        dp[j] = arr[j]  # Initialize with the element itself
        for i_idx in range(j):
            if arr[i_idx] < arr[j]:
                dp[j] = max(dp[j], dp[i_idx] + arr[j])
        max_sum = max(max_sum, dp[j])

    if k > i:
        return max_sum
    else:
        return max_sum

