def max_Product(arr):
    if len(arr) < 2:
        return (arr[0], arr[1])

    # Find the two largest numbers
    max1 = max(arr)
    max2 = -float('inf')

    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    # Find the two smallest numbers
    min1 = min(arr)
    min2 = float('inf')

    for num in arr:
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    product1 = max1 * max2
    product2 = min1 * min2

    if product1 > product2:
        return (max2, max1)
    else:
        return (min1, min2)

