def sum_Of_product(n):
    if n < 0:
        return 0
    row = [1] * (n + 1)
    for i in range(1, n):
        row[i] = row[i - 1] * (n - i + 1) // i
    total = 0
    for i in range(n):
        total += row[i] * row[i + 1]
    return total
