def sum_in_range(l, r):
    if l % 2 == 1:
        first = l
    else:
        first = l + 1
    if r % 2 == 1:
        last = r
    else:
        last = r - 1
    if first > last:
        return 0
    else:
        n = ((last - first) // 2) + 1
        return (first + last) * n // 2

assert sum_in_range(2, 5) == 8
