def remove_nested(t):
    result = []
    for element in t:
        if not isinstance(element, tuple):
            result.append(element)
        else:
            # Recursively process the elements inside the tuple
            # But do not add the tuple itself to the result
            for sub_element in element:
                result.append(sub_element)
    return tuple(result)

